*{box-sizing:border-box;margin:0;padding:0}
:root{--bg:#0e141b;--panel:#16202c;--panel2:#1c2a3a;--line:#2a3d52;--txt:#e8eef5;--mut:#93a5b8;--acc:#ffb020;--acc2:#ff7847;--ok:#39d98a}
html,body{height:100%}
body{background:var(--bg);color:var(--txt);font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;overflow:hidden;display:flex;flex-direction:column}
header{display:flex;align-items:center;gap:14px;padding:10px 16px;background:linear-gradient(90deg,#131e2b,#182838);border-bottom:1px solid var(--line);flex-wrap:wrap;z-index:5}
.brand{font-size:20px;font-weight:800;letter-spacing:.2px;white-space:nowrap}
.brand span{color:var(--acc)}
.sub{font-size:12px;color:var(--mut);white-space:nowrap}
.spacer{flex:1}
.btn{border:0;border-radius:10px;padding:10px 18px;font-weight:800;font-size:14px;cursor:pointer;letter-spacing:.3px}
.btn-test{background:linear-gradient(180deg,#ffc53d,#ff9f1a);color:#231600;box-shadow:0 4px 18px rgba(255,176,32,.35);min-width:110px}
.btn-test:hover{filter:brightness(1.07)} .btn-test:active{transform:translateY(1px)}
.btn-reset{background:#24364c;color:var(--txt);border:1px solid var(--line)}
.btn-reset:hover{background:#2c425e}
main{flex:1;display:flex;min-height:0}
#stage{flex:1;position:relative;min-width:0;background:#87b7d9}
canvas{display:block;width:100%;height:100%}
aside{width:300px;flex:0 0 300px;background:var(--panel);border-left:1px solid var(--line);padding:14px;overflow-y:auto}
aside h2{font-size:13px;text-transform:uppercase;letter-spacing:1.2px;color:var(--mut);margin:4px 0 12px}
.ctl{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:10px}
.ctl label{display:flex;justify-content:space-between;font-size:13px;font-weight:700;margin-bottom:8px}
.ctl label output{color:var(--acc);font-variant-numeric:tabular-nums}
.ctl .row{display:flex;gap:8px;align-items:center}
input[type=range]{flex:1;accent-color:var(--acc);height:22px}
input[type=number]{width:74px;background:#0f1924;color:var(--txt);border:1px solid var(--line);border-radius:8px;padding:6px 7px;font-size:13px}
