<body>
<header>
  <div>
    <div class="brand">muse-wonder-full-1.0 <span>· Crash Lab</span></div>
    <div class="sub">2D rigid-body crash experiment — car vs. freestanding brick wall</div>
  </div>
  <div class="spacer"></div>
  <button class="btn btn-test" id="btnTest" title="Reset to current settings and launch the car">▶ Test</button>
  <button class="btn btn-reset" id="btnReset" title="Rebuild the scene without launching">↺ Reset</button>
</header>
<main>
  <section id="stage"><canvas id="cv"></canvas></section>
  <aside>
    <h2>Settings</h2>
    <div id="controls"></div>
    <div id="status">Ready — press Test to launch.</div>
    <h2>Telemetry</h2>
    <div class="tele">
      <div class="stat"><b id="tSpeed">0.0</b><span>Car speed m/s</span></div>
      <div class="stat"><b id="tTime">0.00</b><span>Elapsed s</span></div>
      <div class="stat"><b id="tMoving">0</b><span>Moving bricks</span></div>
      <div class="stat"><b id="tBricks">0</b><span>Total bricks</span></div>
      <div class="stat"><b id="tKe">0</b><span>Car KE kJ</span></div>
      <div class="stat"><b id="tMom">0</b><span>Car momentum k·kg·m/s</span></div>
    </div>
    <h2>Fixed physics constants</h2>
    <div class="defaults">
      Brick size <b>0.50 × 0.24 m</b> · Gravity <b>9.81 m/s²</b><br>
      Brick friction <b>0.72</b> · Restitution <b>0.18</b><br>
      Car mass <b>1,250 kg</b> · Car <b>4.2 × 1.45 m</b><br>
      Ground friction <b>0.85</b> · Nominal scale <b>80 px/m</b> (auto-fit)<br>
      Depth layers are parallel wall planes (pseudo-depth offset); bricks collide within their plane, all planes collide with car &amp; ground.
    </div>
    <p class="hint" style="margin-top:10px">Tip: lower the speed or raise brick mass / depth and the wall may only topple or partially survive. Press <b>Test</b> again to repeat the exact same run — the simulation is deterministic.</p>
  </aside>
</main>
<script>
"use strict";
/* ================= Config (mandatory defaults) ================= */
const FIXED = {
  brickW:0.50, brickH:0.24, gravity:9.81, brickFriction:0.72, restitution:0.18,
  carMass:1250, carW:4.2, carH:1.45, groundFriction:0.85, nominalScale:80
};
const PARAMS = [
  {key:"speed", label:"Car speed", unit:"m/s", min:5,  max:45, step:0.5, def:22},
  {key:"cols",  label:"Wall columns", unit:"bricks", min:4, max:24, step:1, def:12},
  {key:"rows",  label:"Wall rows", unit:"bricks", min:3, max:16, step:1, def:8},
  {key:"depth", label:"Wall depth layers", unit:"layers", min:1, max:5, step:1, def:2},
  {key:"brickMass", label:"Brick mass", unit:"kg", min:0.5, max:12, step:0.1, def:2.5},
];
const settings = {}; PARAMS.forEach(p=>settings[p.key]=p.def);
"}

